cd /home/user/rork-app && bun -e '
const ownerAt = await Bun.file("/tmp/owner_at").text();

// 1. Final status of the certification test task
const taskId = "20f65308-235c-49df-9167-6835a843c099";
const res1 = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs/" + taskId, {
  headers: { "Authorization": "Bearer " + ownerAt },
});
const d1 = await res1.json();
const t = d1.task ?? {};
console.log("=== CERT TASK 20f65308 ===");
console.log("status=" + t.status, "checkpoint=" + t.checkpoint, "terminal=" + t.terminal);
console.log("commitSha=" + t.commitSha, "deployId=" + t.renderDeployId, "runtimeSha=" + t.runtimeSha);
console.log("filesChanged=" + JSON.stringify(t.filesChanged));
console.log("error=" + (t.errorMessage ?? "").slice(0,200));
console.log("updated=" + t.updatedAt);

// 2. List ALL senior dev tasks to see the track record
const res2 = await fetch("https://api.ivxholding.com/api/ivx/senior-developer/worker/jobs?limit=20", {
  headers: { "Authorization": "Bearer " + ownerAt },
});
const d2 = await res2.json();
const tasks = d2.tasks ?? d2.jobs ?? [];
console.log("\n=== ALL SENIOR DEV TASKS (last 20) ===");
for (const j of tasks) {
  console.log(j.trace_id?.slice(-12) + " | " + j.status + " | " + (j.checkpoint??".") + " | sha=" + (j.commitSha??".") + " | proof=" + (j.proof_ledger_id??".").slice(0,8) + " | " + (j.errorMessage??".").slice(0,80));
}
' 2>&1 | head -40

