input.command:
cd /home/user/rork-app && bun -e '
const ownerAt = await Bun.file("/tmp/owner_at").text();
// 3. App Factory agents state
const res = await fetch("https://api.ivxholding.com/api/ivx/factory/agents", {
  headers: { "Authorization": "Bearer " + ownerAt },
});
const d = await res.json();
console.log("STATUS=" + res.status);
const agents = d.agents ?? d.data ?? d ?? [];
if (Array.isArray(agents)) {
  console.log("TOTAL_AGENTS=" + agents.length);
  const first12 = agents.slice(0,12);
  for (const a of first12) {
    console.log((a.agent_id??a.id??".") + " | " + (a.role??a.agent_role??".") + " | " + (a.status??a.state??"."));
  }
} else {
  console.log(JSON.stringify(d).slice(0,500));
}
' 2>&1 | head -20

